#include "codegen_internal.h"

#include <inttypes.h>
#include <string.h>
#include "optimizer_helpers.h"

void cg_print_nl(FILE* out) {
  fputs("\n", out);
}

void cg_print_ws(FILE* out) {
  fputs(" ", out);
}

void cg_print_preamble(FILE* out) {
  fputs(".IFJcode26", out);
  cg_print_nl(out);
}

void cg_print_int(FILE* out, IrInt value) {
  fprintf(out, "int@%" PRId64, value);
}

/**
 * @brief Emit a Double literal in round-trippable hexadecimal form.
 *
 * @param out Target output stream.
 * @param value Literal value to emit.
 */
static void cg_print_float(FILE* out, IrDouble value) {
  fprintf(out, "float@%a", value);
}

/**
 * @brief Emit a Boolean literal in IFJcode26 syntax.
 *
 * @param out Target output stream.
 * @param value Literal value to emit.
 */
static void cg_print_bool(FILE* out, IrBool value) {
  fputs(value ? "bool@true" : "bool@false", out);
}

/**
 * @brief Emit the target's nil operand.
 *
 * @param out Target output stream.
 */
static void cg_print_nil(FILE* out) {
  fputs("nil@nil", out);
}

/**
 * @brief Emit a string literal, escaping bytes that are special in IFJcode26.
 *
 * @param out Target output stream.
 * @param str String bytes to escape and emit.
 */
static void cg_print_string(FILE* out, char* str) {
  fputs("string@", out);
  unsigned char* s = (unsigned char*)str;
  size_t s_len = strlen(str);
  for (size_t i = 0; i < s_len; i++) {
    if (s[i] <= 32 || s[i] == 35 || s[i] == 92 || s[i] >= 127) {
      fprintf(out, "\\%03u", s[i]);
    } else {
      fputc(s[i], out);
    }
  }
}

void cg_print_localframe_val(FILE* out, size_t id) {
  fprintf(out, "LF@val_%zu", id);
}

void cg_print_localframe_slot(FILE* out, size_t id) {
  fprintf(out, "LF@slot_%zu", id);
}

void cg_print_tempframe_slot(FILE* out, size_t id) {
  fprintf(out, "TF@slot_%zu", id);
}

void cg_print_value(FILE* out, const CgPlacement* placement, IrValueId id) {
  if (placement[id].slot != IR_INVALID_ID) {
    cg_print_localframe_slot(out, placement[id].slot);
  } else {
    cg_print_localframe_val(out, placement[id].local);
  }
}

